def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_opp = history[-1]

    opp_d = 0
    cc = 0
    cd = 0
    for my, op in history:
        if op == 'D':
            opp_d += 1
        if my == 'C' and op == 'C':
            cc += 1
        elif my == 'C' and op == 'D':
            cd += 1

    if n >= 5:
        recent = history[-5:]
    else:
        recent = history
    opp_d5 = 0
    for my, op in recent:
        if op == 'D':
            opp_d5 += 1

    cons_opp_d = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        cons_opp_d += 1
        i -= 1

    cons_my_d = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'D':
        cons_my_d += 1
        i -= 1

    punished_recent = False
    start = max(0, n - 20)
    for i in range(start, n - 1):
        if history[i][0] == 'D' and history[i][1] == 'C' and history[i + 1][1] == 'D':
            punished_recent = True
            break

    exploit_confirmed = False
    start = max(0, n - 30)
    for i in range(start, n - 1):
        if history[i][0] == 'D' and history[i][1] == 'C' and history[i + 1][0] == 'C' and history[i + 1][1] == 'C':
            if not punished_recent:
                exploit_confirmed = True
                break

    if last_opp == 'D':
        if last_my == 'C':
            if n >= 2 and history[-2][0] == 'D':
                return 'C'
            return 'D'
        else:
            if cc == 0:
                if cons_opp_d >= 5 and cons_my_d >= 3 and cd <= 2:
                    return 'C'
                return 'D'

            if exploit_confirmed:
                return 'C'

            if n >= 2 and history[-2][0] == 'C' and history[-2][1] == 'D':
                if cc >= 5 and cd <= 2 and cons_opp_d <= 3 and opp_d * 2 <= n + 4:
                    return 'C'
                return 'D'

            if n >= 2 and history[-2][0] == 'D':
                if cc > 0 and opp_d * 10 <= n * 8 and cons_opp_d <= 4:
                    return 'C'
                return 'D'

            if cons_opp_d >= 6:
                return 'D'

            if cc >= 3 and opp_d * 10 <= n * 7 and cons_opp_d <= 5:
                return 'C'

            if cc > 0 and opp_d * 2 <= n and cons_opp_d <= 5:
                return 'C'

            return 'D'

    else:
        if last_my == 'D':
            if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'C':
                if not punished_recent and opp_d * 10 <= n * 5 and opp_d5 <= 2:
                    return 'D'
                return 'D'

            if n >= 2 and history[-2][0] == 'C' and history[-2][1] == 'C':
                if exploit_confirmed and not punished_recent and opp_d <= max(1, n // 10) and opp_d5 == 0:
                    return 'D'
                return 'C'

            if n >= 2 and history[-2][0] == 'C' and history[-2][1] == 'D':
                return 'C'

            if exploit_confirmed and not punished_recent and opp_d * 10 <= n * 4:
                return 'D'

            if cc > 0 and opp_d * 2 <= n:
                return 'C'

            return 'D'

        else:
            if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'C':
                if not punished_recent and opp_d * 5 <= n and cc >= max(1, n - 2):
                    return 'D'

            if exploit_confirmed and not punished_recent and opp_d * 5 <= n and opp_d5 <= 1:
                return 'D'

            if opp_d == 0 and (n == 6 or n == 12 or n == 24 or n == 48):
                return 'D'

            return 'C'
